数列 $\{a_n\}$ が実数 $\alpha$ に収束するとは，「どんな正の数 $\varepsilon$ に対しても，ある自然数 $N$ があって，$n\ge N$ を満たすすべての自然数 $n$ について $|a_n-\alpha|<\varepsilon$ が成り立つ」ことをいう．$a_n=\dfrac{2n+1}{n+3}$ とし，$\alpha=2$ とする．
\begin{enumerate}
\item $|a_n-2|$ を $n$ の式で表せ．
\item $\varepsilon=\dfrac{1}{100}$ のとき，$|a_n-2|<\varepsilon$ を満たす最小の自然数 $n$ を求めよ．
\item 任意の $\varepsilon>0$ に対して上の定義の $N$ が取れることを示し，$a_n\to 2$ を証明せよ．
\end{enumerate}

\begin{enumerate}
\item 級数 $\displaystyle\sum_{n=1}^{\infty}\frac{(n!)^2}{(2n)!}$ について，$b_n=\dfrac{(n!)^2}{(2n)!}$ とおくとき $\displaystyle\lim_{n\to\infty}\frac{b_{n+1}}{b_n}$ を求め，この級数が収束することを示せ．
\item $|x|<1$ で $\displaystyle\sum_{n=0}^{\infty}x^n=\frac{1}{1-x}$ が成り立つことを用い，項別微分によって $\displaystyle\sum_{n=1}^{\infty}n^2x^n$ を $x$ の式で表せ．
\item $\displaystyle\sum_{n=1}^{\infty}\frac{n^2}{2^n}$ の値を求めよ．
\end{enumerate}

ガンマ関数 $\Gamma(s)=\displaystyle\int_0^\infty t^{s-1}e^{-t}\,dt$，ベータ関数 $B(p,q)=\displaystyle\int_0^1 x^{p-1}(1-x)^{q-1}\,dx$ $(s,p,q>0)$ について，$\Gamma(s+1)=s\Gamma(s)$，$\Gamma(\frac12)=\sqrt\pi$，$B(p,q)=\dfrac{\Gamma(p)\Gamma(q)}{\Gamma(p+q)}$ を用いてよい．
\begin{enumerate}
\item $\displaystyle\int_0^\infty x^3e^{-2x}\,dx$ を求めよ．
\item $\displaystyle\int_0^1 x^2(1-x)^3\,dx$ を求めよ．
\item $x=\sin^2\theta$ と置換して $B(p,q)=2\displaystyle\int_0^{\pi/2}\sin^{2p-1}\theta\cos^{2q-1}\theta\,d\theta$ を導き，$\displaystyle\int_0^{\pi/2}\sin^4\theta\cos^2\theta\,d\theta$ を求めよ．
\end{enumerate}

$n=1,2,\dots$ に対し $[0,1]$ 上の関数 $f_n(x)=nxe^{-nx^2}$ を考える．
\begin{enumerate}
\item 各 $x\in[0,1]$ で $f_n(x)\to0$ $(n\to\infty)$ である．一方，$\displaystyle\lim_{n\to\infty}\int_0^1f_n(x)\,dx$ を求めよ．
\item $M_n=\displaystyle\sup_{0\le x\le1}f_n(x)$ を $n$ の式で表せ．
\item $\{f_n\}$ は $[0,1]$ 上で $0$ に一様収束しないが，任意の $0<\delta<1$ に対し $[\delta,1]$ 上では一様収束することを示せ．
\end{enumerate}

$a\ge0$ に対し $I(a)=\displaystyle\int_0^\infty\frac{\log(1+a^2x^2)}{1+x^2}\,dx$ とする．積分記号下での微分は許されるものとしてよい．
\begin{enumerate}
\item $a>0$ のとき $I'(a)$ を求めよ．
\item $I(a)$ を求めよ．
\item $\displaystyle\int_0^{\pi/2}\log(\cos\theta)\,d\theta$ の値を求めよ．
\end{enumerate}

$n=0,1,2,\dots$ に対し $a_n=\displaystyle\int_0^1\frac{x^n}{1+x}\,dx$ とする．
\begin{enumerate}
\item $a_n+a_{n+1}$ を $n$ の式で表せ．また $a_0$ を求めよ．
\item $\displaystyle\lim_{n\to\infty}na_n$ を求めよ．
\item $\displaystyle\lim_{n\to\infty}n\left(na_n-\frac12\right)$ を求めよ．
\end{enumerate}

$I_n=\displaystyle\int_0^{\pi/2}\sin^n x\,dx$ $(n=0,1,2,\dots)$ とする．
\begin{enumerate}
\item $n\ge2$ に対し $I_n=\dfrac{n-1}{n}I_{n-2}$ を示し，$nI_nI_{n-1}$ $(n\ge1)$ の値を求めよ．
\item $I_n$ が $n$ について単調減少であることを用いて，$\displaystyle\lim_{n\to\infty}\sqrt{n}\,I_n$ を求めよ．
\item $\displaystyle\lim_{n\to\infty}\frac{\sqrt n}{4^n}\binom{2n}{n}$ を求めよ．
\end{enumerate}

平面の領域 $D$ 上の重積分 $\displaystyle\iint_Df(x,y)\,dx\,dy$ は，$D=\{(x,y)\mid a\le x\le b,\ g(x)\le y\le h(x)\}$ の形のとき $\displaystyle\int_a^b\left(\int_{g(x)}^{h(x)}f(x,y)\,dy\right)dx$ で計算できる（累次積分）．また極座標 $x=r\cos\theta$，$y=r\sin\theta$ を使うと $dx\,dy=r\,dr\,d\theta$ と置き換えられる．
\begin{enumerate}
\item $D=\{(x,y)\mid0\le y\le x\le1\}$ のとき $\displaystyle\iint_Dxy\,dx\,dy$ を求めよ．
\item $E=\{(x,y)\mid x^2+y^2\le1\}$ のとき $\displaystyle\iint_E(x^2+y^2)\,dx\,dy$ を求めよ．
\end{enumerate}

$F(x,y)=x^2+xy+y^3-3$ とし，曲線 $F(x,y)=0$ 上の点 $(1,1)$ を考える．
\begin{enumerate}
\item $F_y(1,1)$ を求め，$(1,1)$ の近くで $F(x,y)=0$ が $y=\varphi(x)$，$\varphi(1)=1$ と一意に解けることを陰関数定理から説明せよ．
\item $\varphi'(1)$ を求めよ．
\item $\varphi''(1)$ を求めよ．
\end{enumerate}

$f(x,y)=5x^2+6xy+5y^2$ を，円 $g(x,y)=x^2+y^2-1=0$ の上で考える．
\begin{enumerate}
\item ラグランジュの未定乗数法の条件 $\nabla f=\lambda\nabla g$，$g=0$ を満たす $\lambda$ の値をすべて求めよ．
\item 円上での $f$ の最大値と最小値を求めよ．
\item 領域 $\{(x,y)\mid5x^2+6xy+5y^2\le1\}$ の面積を求めよ．
\end{enumerate}

\begin{enumerate}
\item $u=x+y$，$v=x-y$ とおくとき，ヤコビアンの絶対値 $\left|\dfrac{\partial(x,y)}{\partial(u,v)}\right|$ を求めよ．
\item $D=\{(x,y)\mid0\le x+y\le2,\ 0\le x-y\le2\}$ に対し $\displaystyle\iint_D(x+y)e^{x-y}\,dx\,dy$ を求めよ．
\item $\displaystyle\iint_{\mathbb{R}^2}e^{-(x^2+xy+y^2)}\,dx\,dy$ を求めよ．ただし $\displaystyle\int_{-\infty}^\infty e^{-t^2}dt=\sqrt\pi$ を用いてよい．
\end{enumerate}
